#include <libxml/parser.h>
#include <libxml/xpath.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    char* name;
    char* age;
    char* citizenship;
} StudentInfo;

/**
Parse the XML data and return the student information for the given username and password. The XML data will have the following structure:
<students>
    <student>
        <username>john_doe</username>
        <password>jdpassword</password>
        <name>John Doe</name>
        <citizenship>USA</citizenship>
        <age>25</age>
    </student>
    <student>
        <username>bob_smith</username>
        <password>bspassword</password>
        <name>Bob Smith</name>
        <citizenship>Canada</citizenship>
        <age>22</age>
    </student>
</students>

We can construct a XPath query and use it to search.

@param xml_data The XML data containing the student information.
@param username The username of the student to search for.
@param password The password of the student to search for.

@return A pointer to a StudentInfo structure if the student is found. Otherwise, returns NULL.
*/
StudentInfo* get_student_info(const char* xml_data, const char* username, const char* password) {
    xmlDocPtr doc = NULL;
    xmlXPathContextPtr context = NULL;
    xmlXPathObjectPtr result = NULL;
    StudentInfo* student_info = NULL;

    // Initialize libxml
    xmlInitParser();
    LIBXML_TEST_VERSION;

    // Parse the XML data
    doc = xmlReadMemory(xml_data, strlen(xml_data), NULL, NULL, 0);
    if (doc == NULL) {
        goto cleanup;
    }

    // Create a XPath context
    context = xmlXPathNewContext(doc);
    if (context == NULL) {
        goto cleanup;
    }

    // Construct the XPath query to find the student by username and password.
    // Using XPath variables to prevent injection vulnerabilities.
    char xpath_query[256];
    snprintf(xpath_query, sizeof(xpath_query), "//student[username=$user and password=$pass]");

    // Set XPath variables
    xmlXPathRegisterVariable(context, (xmlChar*)"user", (xmlChar*)username);
    xmlXPathRegisterVariable(context, (xmlChar*)"pass", (xmlChar*)password);

    // Evaluate the XPath query
    result = xmlXPathEvalExpression((xmlChar*)xpath_query, context);
    if (result == NULL) {
        goto cleanup;
    }

    // Check if any student was found
    if (result->nodesetval != NULL && result->nodesetval->nodeNr > 0) {
        xmlNodePtr student_node = result->nodesetval->nodeTab[0];

        // Allocate memory for StudentInfo
        student_info = (StudentInfo*)malloc(sizeof(StudentInfo));
        if (student_info == NULL) {
            goto cleanup;
        }
        memset(student_info, 0, sizeof(StudentInfo));

        // Extract student details
        xmlNodePtr cur = student_node->children;
        while (cur != NULL) {
            if (xmlStrEqual(cur->name, (xmlChar*)"name")) {
                if (cur->children != NULL && cur->children->content != NULL) {
                    student_info->name = strdup((const char*)cur->children->content);
                }
            } else if (xmlStrEqual(cur->name, (xmlChar*)"age")) {
                if (cur->children != NULL && cur->children->content != NULL) {
                    student_info->age = strdup((const char*)cur->children->content);
                }
            } else if (xmlStrEqual(cur->name, (xmlChar*)"citizenship")) {
                if (cur->children != NULL && cur->children->content != NULL) {
                    student_info->citizenship = strdup((const char*)cur->children->content);
                }
            }
            cur = cur->next;
        }
    }

cleanup:
    // Free resources
    if (result) {
        xmlXPathFreeObject(result);
    }
    if (context) {
        // Unregister variables before freeing context
        xmlXPathUnregisterVariable(context, (xmlChar*)"user");
        xmlXPathUnregisterVariable(context, (xmlChar*)"pass");
        xmlXPathFreeContext(context);
    }
    if (doc) {
        xmlFreeDoc(doc);
    }
    xmlCleanupParser();

    return student_info;
}
